/* Supplemental review guidance, never counted as benchmark controls or compliance. */
(()=>{'use strict';
const entries={
 '3':[['Define log retention and central forwarding requirements.','Define log retention and central forwarding requirements.'],['Review event-log access permissions; see section 17 for audit controls.','Review event-log access permissions; see section 17 for audit controls.'],'17'],
 '4':[['Inventory local Administrators and other privileged group memberships.','Inventory local Administrators and other privileged group memberships.'],['Define approved membership and preserve recovery access before enforcement.','Define approved membership and preserve recovery access before enforcement.'],'2'],
 '6':[['Review ACLs and inheritance on sensitive registry keys.','Review ACLs and inheritance on sensitive registry keys.'],['Controls configuring registry values appear in section 18 and other policy sections.','Controls configuring registry values appear in section 18 and other policy sections.'],'18'],
 '7':[['Review NTFS/share permissions and inheritance for sensitive directories.','Review NTFS/share permissions and inheritance for sensitive directories.'],['Before changing permissions, review ACL backups and application-account access.','Before changing permissions, review ACL backups and application-account access.'],'2'],
 '8':[['Inventory 802.1X/EAP support, certificates and switch/RADIUS requirements.','Inventory 802.1X/EAP support, certificates and switch/RADIUS requirements.'],['Pilot network-access policy separately and retain recovery connectivity.','Pilot network-access policy separately and retain recovery connectivity.'],'9'],
 '10':[['Review correct Domain, Private and Public network-profile classification.','Review correct Domain, Private and Public network-profile classification.'],['Review unidentified networks and profile-change permissions against organizational requirements.','Review unidentified networks and profile-change permissions against organizational requirements.'],'9'],
 '11':[['Define approved Wi-Fi profiles and authentication/certificate requirements.','Define approved Wi-Fi profiles and authentication/certificate requirements.'],['Test on limited devices and account for connectivity loss.','Test on limited devices and account for connectivity loss.'],'9'],
 '12':[['Review trusted roots, certificate expiration and revocation requirements.','Review trusted roots, certificate expiration and revocation requirements.'],['Assess CA/template permissions separately before auto-enrollment.','Assess CA/template permissions separately before auto-enrollment.'],'2'],
 '13':[['Review existing software restriction rules and application inventory.','Review existing software restriction rules and application inventory.'],['Assess App Control/AppLocker compatibility for new application control; start with audit/pilot.','Assess App Control/AppLocker compatibility for new application control; start with audit/pilot.'],'15'],
 '14':[['Determine whether this legacy GPMC category is used in your environment.','Determine whether this legacy GPMC category is used in your environment.'],['Assess network admission through the organization’s supported NAC/802.1X solution.','Assess network admission through the organization’s supported NAC/802.1X solution.'],'8'],
 '15':[['Inventory applications and exceptions; assess AppLocker/App Control compatibility.','Inventory applications and exceptions; assess AppLocker/App Control compatibility.'],['Start with audit/pilot and approve enforcement separately.','Start with audit/pilot and approve enforcement separately.'],'18'],
 '16':[['Review IPsec authentication, certificate/Kerberos and traffic dependencies.','Review IPsec authentication, certificate/Kerberos and traffic dependencies.'],['Pilot Connection Security Rules and preserve management connectivity.','Pilot Connection Security Rules and preserve management connectivity.'],'9']
};
function render(state,domain,esc,say){const entry=entries[domain.id];if(!entry)return `<p class="domain-empty">${'This imported catalog section has no standalone controls.'}</p>`;
 const lang=1,related=state.catalog.sections.find(x=>x.id===entry[2]);
 return `<section class="domain-guidance" data-domain-guidance="${esc(domain.id)}"><span class="domain-guidance-badge">${'SUPPLEMENTAL GUIDANCE · NOT A CIS CONTROL'}</span><h3>${esc(domain.title)} · ${'what should you review?'}</h3><p>${'This imported catalog has no standalone controls in this GPMC category. It remains for structure and related security topics; these recommendations do not add to the 405 controls or compliance results.'}</p><ul><li>${esc(entry[0][lang])}</li><li>${esc(entry[1][lang])}</li></ul>${related?`<button type="button" data-breadcrumb-domain="${esc(related.id)}">${'Open related section'}: ${esc(related.title)} →</button>`:''}<a href="https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/security-policy-settings" target="_blank" rel="noopener noreferrer">${'Microsoft policy documentation'} ↗</a></section>`;
}
window.GpoDomainGuidance=Object.freeze({render});
})();
